-- Economics Gen2 Season 2 Tour 4. Versioned hard and medium content, 6 easy/10 medium/4 hard.
-- Does not touch legacy Season 1 and aborts if there is learner history on the target season.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='75s';
DO $tour1$
DECLARE
 d jsonb:='[{"ref":"EC9708:G2:EC9708-G2-T4-T-001","d":"hard","sec":135,"k":"C","en":"A price-taking workshop sells 100 units at $9 each. At this output its average variable cost is $7 and average total cost is $12. Assume all fixed costs must still be paid if it closes temporarily, and the 100 units are the best feasible positive output. What is its operating loss, its shutdown loss, and its better short-run decision?","ru":"Мастерская-ценополучатель продаёт 100 изделий по $9. При этом средние переменные затраты $7, средние общие затраты $12. Все постоянные затраты придётся платить и при временном закрытии, а 100 изделий — лучший возможный положительный выпуск. Каковы убыток при работе, убыток при закрытии и лучшее краткосрочное решение?","uz":"Narx qabul qiluvchi ustaxona 100 mahsulotni har birini $9 dan sotadi. Shu hajmda o‘rtacha o‘zgaruvchi xarajat $7, o‘rtacha jami xarajat $12. Vaqtincha yopilganda ham barcha doimiy xarajatlar to‘lanadi, 100 dona eng yaxshi musbat ishlab chiqarish. Ishlashdagi zarar, yopilishdagi zarar va qisqa muddatdagi eng yaxshi qaror qanday?","options_en":["Operating loss $300; shutdown loss $200; close","Operating loss $500; shutdown loss $300; close","Operating loss $300; shutdown loss $500; keep producing","Operating profit $200; shutdown loss $500; keep producing"],"options_ru":["Убыток при работе $300, при закрытии $200; закрыть","Убыток при работе $500, при закрытии $300; закрыть","Убыток при работе $300, при закрытии $500; продолжать выпуск","Прибыль $200, убыток при закрытии $500; продолжать выпуск"],"options_uz":["Ishlash zarari $300, yopilish zarari $200; yopish","Ishlash zarari $500, yopilish zarari $300; yopish","Ishlash zarari $300, yopilish zarari $500; ishlab chiqarishni davom ettirish","Ishlash foydasi $200, yopilish zarari $500; davom ettirish"],"why":["Revenue=100×$9=$900. Total cost=100×$12=$1,200, operating loss=$300. Variable cost=$700; fixed cost=$500, so shutdown loses $500. Continue: revenue covers variable cost plus $200 of fixed cost.","Выручка $900, общие затраты $1 200, убыток при работе $300. Переменные затраты $700, постоянные $500 — столько теряется при закрытии. Работать выгоднее, поскольку выручка покрывает переменные затраты и $200 постоянных.","Tushum $900, jami xarajat $1200, ishlash zarari $300. O‘zgaruvchi xarajat $700, doimiy xarajat $500, yopilsa $500 zarar. Ishlab chiqarish davom etsa doimiy xarajatning $200 qismi qoplanadi."]},{"ref":"EC9708:G2:EC9708-G2-T4-T-005","d":"hard","sec":135,"k":"B","en":"A consumer has $9 to spend on two goods, bought in whole units. X costs $3; its first three units yield marginal utilities 12, 9 and 5. Y costs $2; its first four units yield marginal utilities 9, 6, 4 and 1. More units are unavailable. Which affordable bundle maximises total utility if marginal utilities are additive?","ru":"Потребитель располагает $9 на два товара, покупаемых целыми единицами. X стоит $3; предельные полезности первых трёх единиц 12, 9, 5. Y стоит $2; предельные полезности первых четырёх единиц 9, 6, 4, 1. Других единиц нет. Какой доступный набор максимизирует суммарную полезность при аддитивности предельных полезностей?","uz":"Iste’molchida ikkita tovar uchun $9 bor, faqat butun birlik olinadi. X $3, dastlabki uch birligining chegaraviy foydaliligi 12, 9, 5. Y $2, dastlabki to‘rt birligining foydaliligi 9, 6, 4, 1. Boshqa birlik mavjud emas. Chegaraviy foydaliliklar qo‘shilsa qaysi arzon to‘plam jami foydalilikni eng yuqori qiladi?","options_en":["2 X and 1 Y: utility 30","1 X and 3 Y: utility 31","3 X and 0 Y: utility 26","0 X and 4 Y: utility 20"],"options_ru":["2 X и 1 Y: полезность 30","1 X и 3 Y: полезность 31","3 X и 0 Y: полезность 26","0 X и 4 Y: полезность 20"],"options_uz":["2 X va 1 Y: foydalilik 30","1 X va 3 Y: foydalilik 31","3 X va 0 Y: foydalilik 26","0 X va 4 Y: foydalilik 20"],"why":["1 X plus 3 Y costs $3+$6=$9 and gives 12+9+6+4=31 utility, above the alternatives. The best bundle balances marginal utility gains against indivisible prices and the budget constraint.","1 X и 3 Y стоят $3+$6=$9, полезность 12+9+6+4=31, выше других наборов. Нужно сопоставлять предельные выгоды с ценой и ограничением бюджета.","1 X va 3 Y $3+$6=$9 turadi, foydalilik 12+9+6+4=31, boshqa variantlardan yuqori. Narx, chegara va qo‘shimcha foydalilik hisobga olinadi."]},{"ref":"EC9708:G2:EC9708-G2-T4-T-014","d":"hard","sec":135,"k":"A","en":"Without preventive checks, a delivery fleet has a 10% chance of a $1,000 repair claim per year. Safety checks cost $40 annually and cut the chance to 2%. A full insurance contract pays every repair bill without a deductible; the premium is fixed during the year regardless of checks. What is the net expected resource saving from doing checks, and what incentive problem may insurance create?","ru":"Без проверок безопасности у автопарка вероятность ежегодного ремонта стоимостью $1 000 равна 10%. Проверки обходятся в $40 в год и снижают вероятность до 2%. Полная страховка покрывает все ремонты без франшизы; страховой взнос за год не зависит от проверок. Какова чистая ожидаемая экономия ресурсов от проверок и какую проблему стимулов может создать страхование?","uz":"Xavfsizlik tekshiruvisiz avtoparkda yiliga $1000 ta’mir ehtimoli 10%. Tekshiruv yiliga $40 turadi va ehtimolni 2% ga tushiradi. To‘liq sug‘urta barcha ta’mirni chegirmasiz qoplaydi; yil davomida badal tekshiruvga bog‘liq emas. Tekshiruvning kutilgan sof resurs tejamkorligi qancha va sug‘urta qanday rag‘bat muammosini yaratadi?","options_en":["$40 net saving; full coverage may create moral hazard by weakening the fleet''s incentive to check safety","$80 net saving; insurance eliminates every accident risk","$20 net loss; checking is socially inefficient","$60 net saving; checks must always increase expected repair costs"],"options_ru":["Чистая экономия $40; полное покрытие может вызвать моральный риск, ослабив стимул к проверкам","Экономия $80; страховка полностью исключает риск аварий","Чистый убыток $20; проверки неэффективны для общества","Экономия $60; проверки обязательно повышают ожидаемый ущерб"],"options_uz":["Sof tejam $40; to‘liq sug‘urta tekshiruv rag‘batini susaytirib axloqiy tavakkal yaratishi mumkin","Tejam $80; sug‘urta baxtsiz hodisani butunlay yo‘q qiladi","Sof zarar $20; tekshiruv ijtimoiy samarasiz","Tejam $60; tekshiruv kutilgan ta’mir xarajatini albatta oshiradi"],"why":["Expected repairs fall from 0.10×$1,000=$100 to 0.02×$1,000=$20, saving $80 before safety-check costs. Net social resource saving=$80−$40=$40. With full fixed-premium coverage, the firm may underinvest in prevention: moral hazard.","Ожидаемый ремонт без проверок $100, с проверками $20 — экономия $80. После затрат на проверку $40 чистый выигрыш $40. Полное страхование ослабляет частный стимул избегать ущерба: моральный риск.","Tekshiruvsiz kutilgan ta’mir $100, tekshiruv bilan $20; tejam $80. $40 tekshiruvdan keyin sof $40. To‘liq sug‘urta oldini olish rag‘batini kamaytiradi: axloqiy tavakkal."]},{"ref":"EC9708:G2:EC9708-G2-T4-T-019","d":"hard","sec":135,"k":"D","en":"A consumer''s successive pastries have money-valued marginal utilities of $18, $14, $10, $6 and $2. Initially each costs $9; later price falls to $5. With no binding income constraint, by how much does the maximum total consumer surplus increase after the price cut?","ru":"Денежная оценка предельных полезностей последовательных пирожных равна $18, $14, $10, $6 и $2. Первоначальная цена $9, затем снижается до $5. Доход не ограничивает выбор. На сколько увеличится максимальный общий излишек потребителя после снижения цены?","uz":"Ketma-ket pishiriqlarning puldagi chegaraviy foydaliligi $18, $14, $10, $6 va $2. Dastlab narx $9, keyin $5 ga tushadi. Daromad cheklovi yo‘q. Narx kamaygach maksimal jami iste’molchi ortiqchaligi qanchaga oshadi?","options_en":["$5","$9","$28","$13"],"options_ru":["$5","$9","$28","$13"],"options_uz":["$5","$9","$28","$13"],"why":["At $9 the first three units are purchased: (18−9)+(14−9)+(10−9)=$15 surplus. At $5 the first four: (18−5)+(14−5)+(10−5)+(6−5)=$28. Increase=$28−$15=$13.","При цене $9 покупаются три единицы, излишек (18−9)+(14−9)+(10−9)=$15. При $5 — четыре, излишек $28. Прирост $28−$15=$13.","$9 narxda uch dona olinadi, ortiqchalik (18−9)+(14−9)+(10−9)=$15. $5 narxda to‘rt dona, ortiqchalik $28. Oshish $13."]},{"ref":"EC9708:G2:EC9708-G2-T4-T-003","d":"medium","sec":115,"k":"B","en":"An established firm with variable costs of $8 per unit charges $20 per unit. A potential entrant needs at least $16 per unit to cover its own average cost. The incumbent temporarily charges $14 to make entry unattractive while remaining above its own variable cost. What strategy is this, and how does the incumbent''s contribution margin per unit change?","ru":"Действующая фирма с переменными затратами $8 на единицу продаёт по $20. Потенциальному конкуренту для покрытия собственных средних затрат нужна цена минимум $16. Действующая фирма временно снижает цену до $14, оставаясь выше переменных затрат, чтобы осложнить вход. Как называется стратегия и как меняется маржинальный доход на единицу?","uz":"Bozordagi firmaning birlik o‘zgaruvchi xarajati $8, narxi $20. Yangi raqobatchi o‘z o‘rtacha xarajatini qoplash uchun kamida $16 narxga muhtoj. Mavjud firma kirishni qiyinlashtirish uchun vaqtincha narxni $14 ga tushiradi, lekin o‘z xarajatidan yuqori qoladi. Bu qanday strategiya va birlik hissa marjasi qanday o‘zgaradi?","options_en":["Predatory pricing; margin becomes negative $2","Limit pricing; contribution per unit falls from $12 to $6","Price discrimination; contribution rises from $12 to $14","Loss leadership; contribution rises from $6 to $12"],"options_ru":["Хищническое ценообразование; маржа становится −$2","Сдерживающее вход ценообразование; маржа снижается с $12 до $6","Ценовая дискриминация; маржа растёт с $12 до $14","Продажи с убытком ради привлечения покупателей; маржа растёт с $6 до $12"],"options_uz":["Yirtqich narx; marja −$2 bo‘ladi","Kirishni cheklovchi narx; birlik hissa $12 dan $6 ga tushadi","Narx diskriminatsiyasi; marja $12 dan $14 ga oshadi","Zararga sotish; marja $6 dan $12 ga oshadi"],"why":["Limit pricing aims to deter entry while retaining a positive contribution for the incumbent. Contribution falls from $20−$8=$12 to $14−$8=$6 per unit.","Ограничивающее вход ценообразование призвано удержать конкурента за пределами рынка. Маржинальный доход на единицу снижается с $20−$8=$12 до $14−$8=$6.","Kirishni cheklovchi narx raqibni bozorga kiritmaslikka qaratilgan. Hissa marjasi $20−$8=$12 dan $14−$8=$6 ga tushadi."]},{"ref":"EC9708:G2:EC9708-G2-T4-T-006","d":"medium","sec":120,"k":"D","en":"A consumer has $120 for goods X and Y, initially priced at $10 and $20 respectively. Later only the price of X falls to $8, with income and Y price unchanged. With X on the horizontal axis and Y vertically, how do the two intercepts of the budget line change?","ru":"Потребитель располагает $120 на товары X и Y, первоначальные цены $10 и $20. Затем цена X снижается до $8 при неизменном доходе и цене Y. Если X расположен по горизонтальной оси, Y — по вертикальной, как изменяются обе точки пересечения бюджетной линии с осями?","uz":"Iste’molchida X va Y uchun $120 bor, dastlabki narxlar $10 va $20. Keyin faqat X narxi $8 ga tushadi, daromad va Y narxi o‘zgarmaydi. X gorizontal, Y vertikal o‘qda bo‘lsa, budjet chizig‘ining ikki o‘qdagi kesishishi qanday o‘zgaradi?","options_en":["X 12→12; Y 6→7.5","X 12→15; Y 6→7.5","X 10→8; Y 20→20","X 12→15; Y stays 6, so the line pivots outward"],"options_ru":["X: 12→12; Y: 6→7,5","X: 12→15; Y: 6→7,5","X: 10→8; Y: 20→20","X: 12→15; Y остаётся 6, линия поворачивается наружу"],"options_uz":["X 12→12; Y 6→7,5","X 12→15; Y 6→7,5","X 10→8; Y 20→20","X 12→15; Y 6 qoladi, chiziq tashqariga buriladi"],"why":["Maximum X rises from $120/$10=12 to $120/$8=15. Maximum Y remains $120/$20=6. The budget line pivots outward around its fixed Y intercept.","Максимум X растёт с $120/$10=12 до $120/$8=15; максимум Y остаётся $120/$20=6. Линия поворачивается вокруг неизменного пересечения с осью Y.","X maksimumi $120/$10=12 dan $120/$8=15 ga oshadi. Y maksimumi $120/$20=6 qoladi. Chiziq Y kesishish nuqtasi atrofida tashqariga buriladi."]},{"ref":"EC9708:G2:EC9708-G2-T4-T-008","d":"medium","sec":120,"k":"C","en":"A firm compares long-run plant sizes: at 20 units average total cost is $14; at 30 units it is $12; at 40 units it rises to $15. Which listed size has the lowest unit cost, what is total cost there, and what happens to average cost at the next listed size?","ru":"Фирма сравнивает долгосрочные размеры предприятия: при выпуске 20 единиц средние общие затраты $14, при 30 — $12, при 40 — $15. При каком указанном выпуске затраты на единицу минимальны, сколько составляют там общие затраты и что происходит со средними затратами на следующем размере?","uz":"Firma uzoq muddatli korxona hajmlarini taqqoslaydi: 20 birlikda o‘rtacha jami xarajat $14, 30 birlikda $12, 40 birlikda $15. Qaysi hajmda birlik xarajati eng past, shu yerda jami xarajat qancha va keyingi hajmda o‘rtacha xarajat qanday o‘zgaradi?","options_en":["20 units; total cost $280; average cost falls at 40","40 units; total cost $600; average cost falls at 40","30 units; total cost $360; average cost then rises from $12 to $15","30 units; total cost $180; average cost stays $12 at 40"],"options_ru":["20 единиц; общие затраты $280; далее средние затраты падают","40 единиц; общие затраты $600; далее средние затраты падают","30 единиц; общие затраты $360; затем средние затраты растут с $12 до $15","30 единиц; общие затраты $180; при 40 средние затраты остаются $12"],"options_uz":["20 birlik; jami xarajat $280; keyin o‘rtacha xarajat tushadi","40 birlik; jami xarajat $600; keyin o‘rtacha xarajat tushadi","30 birlik; jami xarajat $360; keyin o‘rtacha xarajat $12 dan $15 ga oshadi","30 birlik; jami xarajat $180; 40 birlikda o‘rtacha xarajat $12 qoladi"],"why":["The lowest listed AC is $12 at Q=30, giving total cost $12×30=$360. At Q=40, AC rises to $15, suggesting diseconomies beyond the minimum listed scale.","Минимальные средние затраты $12 при Q=30, общие затраты $12×30=$360. При Q=40 средние затраты растут до $15, что указывает на отрицательный эффект масштаба после минимума.","Eng past AC $12 Q=30 da, jami xarajat $12×30=$360. Q=40 da AC $15 ga oshadi, bu keyingi hajmda miqyos samarasizligini ko‘rsatadi."]},{"ref":"EC9708:G2:EC9708-G2-T4-T-015","d":"medium","sec":115,"k":"A","en":"A cinema sells 200 discounted student tickets at $6 and 300 adult tickets at $11, with no resale. Assume exactly the same 500 customers would attend under a uniform $8 price. What is ticket revenue under the two-price system compared with the uniform-price alternative?","ru":"Кинотеатр продаёт 200 студенческих билетов по $6 и 300 взрослых по $11, перепродажа невозможна. Предположим, те же 500 зрителей пришли бы при единой цене $8. Какова выручка при двух ценах по сравнению с единой ценой?","uz":"Kinoteatr qayta sotishsiz 200 talabaga $6 dan, 300 kattaga $11 dan chipta sotadi. Faraz qilaylik, ayni 500 tomoshabin yagona $8 narxda ham keladi. Ikki xil narxdagi tushum yagona narxga nisbatan qanday?","options_en":["$4,500 vs $4,000; differential pricing earns $500 more under the assumptions","$4,000 vs $4,500; differential pricing earns $500 less","$5,500 vs $4,000; differential pricing earns $1,500 more","$4,500 vs $4,500; no difference"],"options_ru":["$4 500 против $4 000; две цены дают на $500 больше при этих допущениях","$4 000 против $4 500; две цены дают на $500 меньше","$5 500 против $4 000; две цены дают на $1 500 больше","$4 500 против $4 500; разницы нет"],"options_uz":["$4500 va $4000; ikki narx bu shartlarda $500 ko‘proq tushum beradi","$4000 va $4500; ikki narx $500 kam tushum beradi","$5500 va $4000; ikki narx $1500 ko‘proq beradi","$4500 va $4500; farq yo‘q"],"why":["Two-price revenue=200×$6+300×$11=$4,500. Uniform revenue=500×$8=$4,000. The $500 difference relies on holding attendance fixed; quantities may respond differently in reality.","Выручка при двух ценах 200×$6+300×$11=$4 500, при единой 500×$8=$4 000. Разница $500 верна лишь при заданном неизменном числе зрителей.","Ikki narxda tushum 200×$6+300×$11=$4500, yagona narxda 500×$8=$4000. $500 farq tomoshabinlar soni o‘zgarmas degan shartga bog‘liq."]},{"ref":"EC9708:G2:EC9708-G2-T4-T-018","d":"medium","sec":120,"k":"B","en":"An owner-run repair business records annual revenue $180,000 and explicit operating costs $125,000. The owner could earn $50,000 in a salaried job; her invested funds could earn a further $10,000 in their next-best alternative use. Assuming these opportunity costs do not overlap, what are accounting profit and economic profit?","ru":"Ремонтная мастерская владельца получает $180 000 годовой выручки при явных операционных затратах $125 000. Владелец мог бы заработать $50 000 по найму; вложенные средства могли бы отдельно приносить ещё $10 000 в лучшем альтернативном использовании. Альтернативные затраты не пересекаются. Найдите бухгалтерскую и экономическую прибыль.","uz":"Egasi boshqaradigan ta’mirlash firmasi yillik $180 000 tushum va $125 000 aniq operatsion xarajatga ega. Egasi ishga kirsa $50 000 topishi, kiritilgan mablag‘ esa alohida eng yaxshi muqobilda $10 000 daromad berishi mumkin. Muqobil xarajatlar takrorlanmaydi. Buxgalteriya va iqtisodiy foyda qancha?","options_en":["Accounting +$55,000; economic +$5,000","Accounting +$55,000; economic −$5,000","Accounting −$5,000; economic +$55,000","Accounting +$180,000; economic +$125,000"],"options_ru":["Бухгалтерская +$55 000; экономическая +$5 000","Бухгалтерская +$55 000; экономическая −$5 000","Бухгалтерская −$5 000; экономическая +$55 000","Бухгалтерская +$180 000; экономическая +$125 000"],"options_uz":["Buxgalteriya +$55 000; iqtisodiy +$5 000","Buxgalteriya +$55 000; iqtisodiy −$5 000","Buxgalteriya −$5 000; iqtisodiy +$55 000","Buxgalteriya +$180 000; iqtisodiy +$125 000"],"why":["Accounting profit=180,000−125,000=$55,000. Economic profit also subtracts the owner''s salary alternative $50,000 and capital opportunity cost $10,000, giving −$5,000.","Бухгалтерская прибыль 180 000−125 000=$55 000. Экономическая вычитает зарплатную альтернативу $50 000 и доход капитала $10 000: −$5 000.","Buxgalteriya foyda 180 000−125 000=$55 000. Iqtisodiy foyda yana muqobil ish haqi $50 000 va kapital daromadi $10 000 ni ayirib, −$5 000 beradi."]}]'::jsonb;
 x jsonb; oldq record; new_id bigint; i int; idx int; keytxt text; reftext text; cnt int;
 enwhy text; ruwhy text; uzwhy text; ez int; med int; hard int;
BEGIN
 IF jsonb_array_length(d)<>9 THEN RAISE EXCEPTION 'T4_nine_replacements_required'; END IF;
 IF EXISTS(SELECT 1 FROM public.tour_attempts at JOIN public.tours t ON t.id=at.tour_id WHERE t.subject_id=7 AND t.season_id=2 AND t.tour_no=4)
 THEN RAISE EXCEPTION 'T4_season2_attempts_exist'; END IF;
 SELECT count(*) INTO cnt FROM public.tours t JOIN public.tour_questions l ON l.tour_id=t.id AND l.is_active
 WHERE t.subject_id=7 AND t.season_id=2 AND t.tour_no=4;
 IF cnt<>20 THEN RAISE EXCEPTION 'T4_pool_not20_before: %',cnt; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(d) LOOP
   reftext:=x->>'ref';keytxt:=x->>'k';idx:=ascii(keytxt)-65;
   IF keytxt NOT IN ('A','B','C','D') OR x->>'d' NOT IN ('hard','medium')
      OR jsonb_array_length(x->'options_en')<>4 OR jsonb_array_length(x->'options_ru')<>4
      OR jsonb_array_length(x->'options_uz')<>4
   THEN RAISE EXCEPTION 'T4_invalid_authoring: %',reftext; END IF;
   SELECT q.id,q.subject_id,q.topic,q.subtopic,q.quality_flag,l.tour_id,l.order_no
   INTO STRICT oldq FROM public.questions q JOIN public.tour_questions l ON l.question_id=q.id AND l.is_active
   JOIN public.tours t ON t.id=l.tour_id
   WHERE q.subject_id=7 AND t.subject_id=7 AND t.season_id=2 AND t.tour_no=4 AND q.book_ref=reftext;
   IF EXISTS(SELECT 1 FROM public.tour_answers a WHERE a.question_id=oldq.id)
      OR EXISTS(SELECT 1 FROM public.tour_session_answers_v4 a WHERE a.question_id=oldq.id)
      OR EXISTS(SELECT 1 FROM public.questions q WHERE q.subject_id=7 AND q.book_ref=reftext||'-V2')
   THEN RAISE EXCEPTION 'T4_history_or_duplicate: %',reftext; END IF;
   enwhy:=x->'why'->>0;ruwhy:=x->'why'->>1;uzwhy:=x->'why'->>2;
   INSERT INTO public.questions(subject_id,topic,subtopic,difficulty,qtype,question_text,options_text,correct_answer,explanation,image_url,is_active,
   question_text_ru,question_text_uz,question_text_en,options_text_ru,options_text_uz,options_text_en,explanation_ru,explanation_uz,explanation_en,book_ref,time_limit_sec,quality_flag,quality_status)
   VALUES(oldq.subject_id,oldq.topic,oldq.subtopic,x->>'d','mcq',x->>'en',(x->'options_en')::text,keytxt,
   'Correct: '||(x->'options_en'->>idx)||E'\n'||enwhy,NULL,true,
   x->>'ru',x->>'uz',x->>'en',(x->'options_ru')::text,(x->'options_uz')::text,(x->'options_en')::text,
   'Правильный ответ: '||(x->'options_ru'->>idx)||E'\n'||ruwhy,
   'To‘g‘ri javob: '||(x->'options_uz'->>idx)||E'\n'||uzwhy,
   'Correct answer: '||(x->'options_en'->>idx)||E'\n'||enwhy,
   reftext||'-V2',(x->>'sec')::int,oldq.quality_flag,'published')
   RETURNING id INTO new_id;
   UPDATE public.tour_questions SET is_active=false WHERE tour_id=oldq.tour_id AND question_id=oldq.id AND is_active;
   GET DIAGNOSTICS cnt=ROW_COUNT;
   IF cnt<>1 THEN RAISE EXCEPTION 'T4_old_link_count: %',reftext; END IF;
   INSERT INTO public.tour_questions(tour_id,question_id,order_no,is_active) VALUES(oldq.tour_id,new_id,oldq.order_no,true);
   INSERT INTO public.question_version_links(old_question_id,new_question_id,link_type,reason)
   VALUES(oldq.id,new_id,'replacement','Economics Gen2 season2 Tour4: actual high-order difficulty replacement; old question preserved');
   FOR i IN 0..3 LOOP
     INSERT INTO public.question_answer_diagnostics(question_id,answer_kind,answer_key,answer_value,is_correct,
        mistake_type,weak_skill,feedback_ru,feedback_uz,feedback_en,next_action_ru,next_action_uz,next_action_en,rule_json,quality_status)
     VALUES(new_id,'mcq_option',chr(65+i),NULL,i=idx,
        CASE WHEN i=idx THEN NULL ELSE 'multi_step_economic_reasoning' END,oldq.subtopic,
        'Выбрано: '||(x->'options_ru'->>i)||E'\n'||ruwhy||E'\nОтвет: '||(x->'options_ru'->>idx),
        'Tanlov: '||(x->'options_uz'->>i)||E'\n'||uzwhy||E'\nJavob: '||(x->'options_uz'->>idx),
        'Selected: '||(x->'options_en'->>i)||E'\n'||enwhy||E'\nCorrect: '||(x->'options_en'->>idx),
        CASE WHEN i=idx THEN NULL ELSE 'Перепроверьте каждый шаг.' END,
        CASE WHEN i=idx THEN NULL ELSE 'Har bir bosqichni tekshiring.' END,
        CASE WHEN i=idx THEN NULL ELSE 'Check each step.' END,
        jsonb_build_object('diagnostic_code','EC9708_G2_T4T'||substring(reftext from 'T-([0-9]{3})')||'_V2_'||chr(65+i)),
        'published');
   END LOOP;
 END LOOP;
 UPDATE public.questions q SET difficulty=
  CASE WHEN right(q.book_ref,3) IN ('007','009','010','012','016','017') THEN 'easy' ELSE 'medium' END
 WHERE q.subject_id=7 AND q.book_ref ~ '^EC9708:G2:EC9708-G2-T4-T-[0-9]{3}$'
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(d) z WHERE z->>'ref'=q.book_ref);
 GET DIAGNOSTICS cnt=ROW_COUNT;
 IF cnt<>11 THEN RAISE EXCEPTION 'T4_unchanged_expected11: %',cnt; END IF;
 SELECT count(*),count(*) FILTER(WHERE q.difficulty='easy'),
 count(*) FILTER(WHERE q.difficulty='medium'),count(*) FILTER(WHERE q.difficulty='hard')
 INTO cnt,ez,med,hard
 FROM public.tours t JOIN public.tour_questions l ON l.tour_id=t.id AND l.is_active
 JOIN public.questions q ON q.id=l.question_id WHERE t.subject_id=7 AND t.season_id=2 AND t.tour_no=4;
 IF cnt<>20 OR ez<>6 OR med<>10 OR hard<>4 THEN
 RAISE EXCEPTION 'T4_mix_invalid: %,%,%,%',cnt,ez,med,hard; END IF;
END $tour1$;
COMMIT;
